import {zones} from './data.js';
const hash=(x,y)=>{let v=Math.sin(x*127.1+y*311.7)*43758.5453;return v-Math.floor(v)};
export function blocked(x,y){return x<1||y<1||x>24||y>24||(x>=18&&y>=4&&y<=11)||(x>=4&&x<=6&&y>=5&&y<=7)||((x+y)%9===0&&hash(x,y)>.86);}
const palettes=[['#3c5c41','#496e46','#5d8150','#76985c','#a0b773'],['#244d47','#326456','#488167','#669177','#9fb990'],['#2e5357','#396a68','#50847e','#78a093','#aec2a2'],['#374c56','#4a6667','#66807c','#8ba18d','#bdc7a5'],['#353b51','#48475c','#635d6a','#8a7e83','#b5a095']];
export function portrait(canvas,index=0,large=false){let c=canvas.getContext('2d');canvas.width=48;canvas.height=64;c.imageSmoothingEnabled=false;c.clearRect(0,0,48,64);let skin=['#e0b58c','#e7c4a2','#d7ac80','#edc7a3','#d8ad8b','#e0b38f'][index%6],hair=['#675344','#a16942','#4e4546','#bd9a56','#4c4644','#6c4951'][index%6],cloth=['#42695a','#7184a4','#8d975d','#d0c4a0','#936f55','#8f6a85'][index%6];let g=c.createLinearGradient(0,0,0,64);g.addColorStop(0,'#c5d3b8');g.addColorStop(1,'#e6e5d3');c.fillStyle=g;c.fillRect(0,0,48,64);c.fillStyle=hair;c.fillRect(12,9,24,34);c.fillRect(8,15,30,22);c.fillStyle=skin;c.fillRect(14,17,20,25);c.fillRect(11,23,26,10);c.fillStyle='#c69471';c.fillRect(21,39,8,7);c.fillStyle=cloth;c.fillRect(8,49,33,15);c.fillRect(15,45,18,10);c.fillStyle='#f0e4ba';c.fillRect(22,46,3,18);c.fillStyle='#263c36';c.fillRect(17,27,3,3);c.fillRect(29,27,3,3);c.fillStyle='#ad7966';c.fillRect(22,36,6,1);c.fillStyle=hair;c.fillRect(11,12,25,9);c.fillRect(15,9,17,8);c.fillRect(10,19,6,11);c.fillRect(29,19,7,6);c.fillStyle='#ffffff32';c.fillRect(14,13,13,3);if(index%2){c.fillStyle='#769477';c.fillRect(10,16,25,3);c.fillStyle='#dcca84';c.fillRect(26,13,4,6);}else{c.fillStyle='#dbd7ba';c.fillRect(11,18,4,4);} }
export class World{
constructor(canvas,state){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.state=state;this.entities=[];this.effects=[];this.marker=null;this.time=0;this.w=800;this.h=440;this.cam={x:0,y:0};this.resize();this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(canvas);}
resize(){this.w=Math.max(320,Math.round(this.canvas.clientWidth));this.h=Math.max(200,Math.round(this.canvas.clientHeight));this.canvas.width=this.w;this.canvas.height=this.h;this.ctx.imageSmoothingEnabled=false;}
project(x,y,z=0){return{x:this.w/2+(x-y)*28-this.cam.x,y:this.h/2+(x+y)*14-this.cam.y-z};}
unproject(px,py){let x=px-this.w/2+this.cam.x,y=py-this.h/2+this.cam.y;return{x:Math.round(x/56+y/28),y:Math.round(y/28-x/56)}}
rect(x,y,w,h,color){this.ctx.fillStyle=color;this.ctx.fillRect(Math.round(x),Math.round(y),w,h)}
poly(points,color){let c=this.ctx;c.fillStyle=color;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(Math.round(x),Math.round(y)):c.moveTo(Math.round(x),Math.round(y)));c.closePath();c.fill();}
tree(x,y,seed,p){let a=this.project(x,y);this.rect(a.x-4,a.y-45,8,43,'#665741');this.rect(a.x-2,a.y-35,4,30,'#897558');this.poly([[a.x-31,a.y-27],[a.x-36,a.y-52],[a.x-16,a.y-81],[a.x+12,a.y-84],[a.x+35,a.y-59],[a.x+31,a.y-29],[a.x,a.y-17]],p[0]);let colors=[p[1],p[2],p[3]];for(let i=0;i<20;i++){let tx=hash(seed+i,1)*48-24,ty=hash(seed+i,2)*47;this.rect(a.x+tx-5,a.y-76+ty,10+Math.floor(hash(i,seed)*14),9,colors[i%3]);}this.rect(a.x-18,a.y-64,11,5,p[4]);}
house(x,y){let a=this.project(x,y);this.poly([[a.x-64,a.y-8],[a.x,a.y+24],[a.x+56,a.y-6],[a.x,a.y-35]],'#4d664a');this.poly([[a.x-53,a.y-17],[a.x,a.y+9],[a.x,a.y-50],[a.x-53,a.y-76]],'#d2cba4');this.poly([[a.x,a.y+9],[a.x+48,a.y-16],[a.x+48,a.y-73],[a.x,a.y-50]],'#a8aa83');this.poly([[a.x-70,a.y-73],[a.x-16,a.y-109],[a.x+60,a.y-74],[a.x+4,a.y-36]],'#696d64');for(let i=0;i<5;i++)this.poly([[a.x-63+i*12,a.y-77-i*6],[a.x-54+i*12,a.y-82-i*6],[a.x+12+i*9,a.y-48-i*6],[a.x+3+i*9,a.y-43-i*6]],i%2?'#858979':'#777e70');this.rect(a.x-42,a.y-35,14,17,'#455d50');this.rect(a.x-39,a.y-33,8,11,'#d7ba70');this.poly([[a.x+16,a.y-4],[a.x+32,a.y-12],[a.x+32,a.y-43],[a.x+16,a.y-35]],'#526151');this.rect(a.x+25,a.y-22,3,3,'#dbbc76');this.rect(a.x-10,a.y-124,12,20,'#8d9181');this.rect(a.x-12,a.y-126,16,4,'#b9b6a0');}
hero(h,leader=false){let a=this.project(h.x,h.y),bob=Math.sin(this.time*8+h.id)* (h.moving?1.5:.4);let c=this.ctx;c.fillStyle='#243e3b38';c.beginPath();c.ellipse(a.x,a.y+2,10,5,0,0,Math.PI*2);c.fill();if(leader){c.strokeStyle='#e8d8a1';c.lineWidth=1;c.beginPath();c.ellipse(a.x,a.y+1,13,6,0,0,Math.PI*2);c.stroke();}let x=a.x,y=a.y+bob,skin='#e3bd95',hair=['#665443','#ad7245','#504748','#b7a05e','#48433d','#73505b'][h.id],cloth=['#426c5e','#6c82a0','#899b63','#d3c8a1','#927351','#936a88'][h.id];this.rect(x-6,y-10,5,10,'#3f4e44');this.rect(x+2,y-10,5,10,'#3f4e44');this.rect(x-7,y-21,15,13,cloth);this.rect(x-10,y-20,4,10,skin);this.rect(x+8,y-20,4,10,skin);this.rect(x-7,y-34,14,14,hair);this.rect(x-6,y-29,12,11,skin);this.rect(x-8,y-35,15,7,hair);this.rect(x-8,y-31,4,9,hair);this.rect(x-3,y-25,2,2,'#344b41');this.rect(x+3,y-25,2,2,'#344b41');this.rect(x-2,y-17,3,8,'#d6c49b');if(h.gear.weapon||h.job!=='novice'){this.rect(x+12,y-27,2,24,'#b2b5a0');this.rect(x+9,y-8,8,2,'#bca266');}if(h.hp<=0){this.rect(x-8,y-2,16,4,'#676e6555');return;}if(leader){c.textAlign='center';c.font='9px system-ui';c.fillStyle='#243e35';c.fillText(h.name,x,y-42);}}
monster(e){let a=this.project(e.x,e.y),t=this.time,hop=Math.sin(t*3+e.x)*2,x=a.x,y=a.y+hop,m=e.m,c=this.ctx;let size=m.boss?1.6:1;c.save();c.translate(Math.round(x),Math.round(y));c.scale(size,size);c.fillStyle='#203c3838';c.beginPath();c.ellipse(0,0,12,5,0,0,Math.PI*2);c.fill();let col=m.color;if(m.type==='slime'){this.rect(-12,-13,24,12,col);this.rect(-9,-19,18,7,col);this.rect(-5,-22,10,5,col);this.rect(-8,-17,5,3,'#d9ede480');this.rect(-6,-10,2,3,'#364b4c');this.rect(4,-10,2,3,'#364b4c');this.rect(-2,-5,4,1,'#435a51');}else if(m.type==='bug'){this.rect(-7,-19,14,17,col);this.rect(-5,-25,10,9,'#655d43');this.rect(-19,-21+Math.sin(t*20)*2,13,8,'#e6e8c0aa');this.rect(7,-21-Math.sin(t*20)*2,13,8,'#e6e8c0aa');this.rect(-6,-12,12,3,'#746c48');this.rect(-4,-23,2,2,'#f4e4b3');this.rect(3,-23,2,2,'#f4e4b3');}else if(m.type==='mushroom'){this.rect(-5,-15,10,14,'#e1ceb4');this.rect(-15,-24,30,10,col);this.rect(-10,-29,20,6,col);this.rect(-7,-26,5,4,'#e9dab9');this.rect(4,-21,5,4,'#e9dab9');this.rect(-3,-9,2,2,'#4a4a3e');this.rect(3,-9,2,2,'#4a4a3e');}else if(m.type==='beast'){this.rect(-13,-18,24,14,col);this.rect(-13,-7,5,8,col);this.rect(5,-7,5,8,col);this.rect(6,-27,12,16,col);this.rect(6,-31,4,7,col);this.rect(14,-30,4,6,col);this.rect(14,-22,3,3,'#eedb9b');this.rect(-19,-21,8,5,col);this.rect(16,-17,5,4,'#4c4d4a');}else if(m.type==='golem'){this.rect(-13,-28,26,23,col);this.rect(-8,-39,16,13,col);this.rect(-19,-26,6,19,col);this.rect(13,-26,6,19,col);this.rect(-12,-7,8,8,col);this.rect(4,-7,8,8,col);this.rect(-5,-34,3,3,'#dde7ac');this.rect(4,-34,3,3,'#dde7ac');this.rect(-4,-23,8,8,'#e4ca80');}else{this.poly([[-12,-2],[-9,-26],[0,-35],[9,-26],[12,-2],[5,-7],[0,-2],[-5,-7]],col);this.rect(-5,-22,3,3,'#e7e4c2');this.rect(3,-22,3,3,'#e7e4c2');}c.restore();if(e.hp<m.hp){this.rect(x-14,y-43*size,28,3,'#294238');this.rect(x-14,y-43*size,28*e.hp/m.hp,3,'#ba7960');}if(m.boss){c.font='9px system-ui';c.textAlign='center';c.fillStyle='#f3e0b1';c.strokeStyle='#403a31';c.lineWidth=3;c.strokeText('♛ '+m.name,x,y-70);c.fillText('♛ '+m.name,x,y-70);}}
render(dt){this.time+=dt;let c=this.ctx,s=this.state,p=palettes[s.zone],leader=s.heroes[s.leader];let targetX=(leader.x-leader.y)*28,targetY=(leader.x+leader.y)*14-15;this.cam.x+=(targetX-this.cam.x)*Math.min(1,dt*5);this.cam.y+=(targetY-this.cam.y)*Math.min(1,dt*5);c.fillStyle=p[2];c.fillRect(0,0,this.w,this.h);for(let sum=0;sum<52;sum++){for(let x=0;x<26;x++){let y=sum-x;if(y<0||y>=26)continue;let a=this.project(x,y);if(a.x< -100||a.x>this.w+100||a.y< -100||a.y>this.h+150)continue;let path=Math.abs(y-13)<1.4||Math.abs(x-12)<1.2;let water=x>=18&&y>=4&&y<=11;let col=water?'#6c9b9b':path?'#b7b494':p[2+Math.floor(hash(x,y)*2)];this.poly([[a.x,a.y-14],[a.x+28,a.y],[a.x,a.y+14],[a.x-28,a.y]],col);if(water){this.rect(a.x-10+Math.sin(this.time+x)*3,a.y,12,1,'#acd0c080');}else if(!path){for(let i=0;i<3;i++){let tx=hash(x+i*3,y)*32-16,ty=hash(y+i*7,x)*12-6;this.rect(a.x+tx,a.y+ty,2,3,p[i%2?1:3]);if(hash(x+34,y+i)>.88)this.rect(a.x+tx,a.y+ty-2,2,2,['#e3d3a1','#c8b2bd','#d7dfb2'][i]);}}}}
let objects=[];for(let x=0;x<26;x++)for(let y=0;y<26;y++){if((Math.abs(y-13)>2&&Math.abs(x-12)>2&&!(x>=18&&y>=3&&y<=12)&&hash(x,y)>.79)||x===0||y===0||x===25||y===25)objects.push({order:x+y,draw:()=>this.tree(x,y,x*29+y,p)});}objects.push({order:11,draw:()=>this.house(5,6)});this.entities.filter(e=>e.hp>0).forEach(e=>objects.push({order:e.x+e.y,draw:()=>this.monster(e)}));s.heroes.filter(h=>h.hp>0).forEach(h=>objects.push({order:h.x+h.y+.1,draw:()=>this.hero(h,h.id===s.leader)}));let camp=this.project(11,12);this.rect(camp.x-9,camp.y-2,18,6,'#6f6c55');this.poly([[camp.x-5,camp.y],[camp.x-6,camp.y-12],[camp.x-2,camp.y-9],[camp.x+1,camp.y-19+Math.sin(this.time*8)*2],[camp.x+6,camp.y-7],[camp.x+4,camp.y]],'#e2b268');objects.sort((a,b)=>a.order-b.order).forEach(o=>o.draw());if(this.marker){let a=this.project(this.marker.x,this.marker.y);c.strokeStyle='#f5e9b7';c.beginPath();c.ellipse(a.x,a.y,13+Math.sin(this.time*5)*2,6,0,0,Math.PI*2);c.stroke();}this.effects=this.effects.filter(e=>e.life>0);for(let e of this.effects){e.life-=dt;let a=this.project(e.x,e.y);c.globalAlpha=Math.min(1,e.life);c.textAlign='center';c.font='bold 14px system-ui';c.strokeStyle='#2c423a';c.lineWidth=3;c.strokeText(e.text,a.x,a.y-40-(1-e.life)*25);c.fillStyle=e.color||'#fff1c0';c.fillText(e.text,a.x,a.y-40-(1-e.life)*25);c.globalAlpha=1;}let grad=c.createRadialGradient(this.w*.5,this.h*.4,0,this.w*.5,this.h*.5,this.w*.8);grad.addColorStop(0,'#f3e8ad0a');grad.addColorStop(1,'#133d3a42');c.fillStyle=grad;c.fillRect(0,0,this.w,this.h);}
}
